const matchProgramType = (lProg: string, formProg: string): boolean => {
  if (!lProg || !formProg) return false;
  if (lProg.trim() === formProg.trim()) return true;
  
  const normVal = (val: string) => {
    const v = val.trim().toLowerCase();
    if (v === 'gdpt2018' || v === 'gdpt 2018' || v === 'kết nối tri thức với cuộc sống' || v === 'ket noi tri thuc voi cuoc song' || v === 'ketnoi') {
      return 'gdpt2018';
    }
    if (v === 'ic3spark' || v === 'ic3 spark' || v === 'tin học quốc tế ic3 spark' || v === 'tin hoc quoc te ic3 spark' || v === 'ic3') {
      return 'ic3spark';
    }
    return v;
  };
  
  return normVal(lProg) === normVal(formProg);
};

const sanitizeUrlInput = (url: string): string => {
  const trimmed = url.trim();
  if (!trimmed) return '';
  if (trimmed.startsWith('http://') || trimmed.startsWith('https://') || trimmed.startsWith('blob:') || trimmed.startsWith('data:') || trimmed.startsWith('<')) {
    return trimmed;
  }
  return `https://${trimmed}`;
};

interface ImageUploaderProps {
  label: string;
  value: string;
  onChange: (val: string) => void;
  id?: string;
}

const ImageUploader: React.FC<ImageUploaderProps> = ({ label, value, onChange, id }) => {
  return (
    <div className="bg-slate-50 border border-slate-200 rounded-xl p-3 space-y-2" id={id}>
      <div className="flex justify-between items-center">
        <span className="text-[10px] font-black text-slate-500 uppercase tracking-wide">{label}</span>
        {value && (
          <button
            type="button"
            onClick={() => onChange('')}
            className="text-[10px] text-rose-500 font-extrabold hover:underline"
          >
            Xóa ảnh
          </button>
        )}
      </div>
      
      {!value ? (
        <label className="flex flex-col items-center justify-center border border-dashed border-slate-300 rounded-lg p-2 bg-white hover:bg-slate-50 transition-colors cursor-pointer">
          <Upload className="w-4 h-4 text-slate-400 mb-0.5" />
          <span className="text-[9px] font-bold text-slate-500">Chọn hoặc thả ảnh tại đây</span>
          <input
            type="file"
            accept="image/*"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) {
                const reader = new FileReader();
                reader.onloadend = () => {
                  onChange(reader.result as string);
                };
                reader.readAsDataURL(file);
              }
            }}
            className="hidden"
          />
        </label>
      ) : (
        <div className="relative border rounded-lg overflow-hidden bg-slate-100 max-h-24 flex justify-center items-center">
          <img src={value} alt="Preview" className="max-h-24 object-contain" referrerPolicy="no-referrer" />
        </div>
      )}
    </div>
  );
};

function getRarityMeta(rarity: string) {
  let raritySymbol = '⚪ Thường';
  let themeClass = {
    bg: 'bg-white hover:shadow-slate-200',
    border: 'border-slate-200 hover:border-slate-350',
    text: 'text-slate-800',
    badge: 'bg-slate-100 text-slate-700 border-slate-250',
    iconBg: 'bg-slate-50 border-slate-100'
  };

  if (rarity === 'Đặc Biệt') {
    raritySymbol = '🟢 Đặc Biệt';
    themeClass = {
      bg: 'bg-emerald-50/20 hover:shadow-emerald-100',
      border: 'border-emerald-200 hover:border-emerald-350',
      text: 'text-emerald-800',
      badge: 'bg-emerald-100/90 text-emerald-800 border-emerald-250',
      iconBg: 'bg-emerald-50 border-emerald-100'
    };
  } else if (rarity === 'Quý') {
    raritySymbol = '🔵 Quý Hiếm';
    themeClass = {
      bg: 'bg-blue-50/20 hover:shadow-blue-100',
      border: 'border-blue-200 hover:border-blue-350',
      text: 'text-blue-800',
      badge: 'bg-blue-100 text-blue-850 border-blue-250',
      iconBg: 'bg-blue-50 border-blue-100'
    };
  } else if (rarity === 'Sử Thi') {
    raritySymbol = '🟣 Sử Thi';
    themeClass = {
      bg: 'bg-purple-50/20 hover:shadow-purple-100',
      border: 'border-purple-200 hover:border-purple-350',
      text: 'text-purple-800',
      badge: 'bg-purple-100 text-purple-850 border-purple-250',
      iconBg: 'bg-purple-50 border-purple-100'
    };
  } else if (rarity === 'Huyền Thoại') {
    raritySymbol = '🟡 Huyền Thoại';
    themeClass = {
      bg: 'bg-amber-50/25 hover:shadow-amber-150',
      border: 'border-amber-250 hover:border-amber-400',
      text: 'text-amber-900',
      badge: 'bg-amber-100 text-amber-900 border-amber-300',
      iconBg: 'bg-amber-50 border-amber-100'
    };
  } else if (rarity === 'Thần Thoại') {
    raritySymbol = '🔴 Thần Thoại';
    themeClass = {
      bg: 'bg-red-50/30 hover:shadow-red-200',
      border: 'border-red-350 hover:border-red-500',
      text: 'text-red-950 font-black',
      badge: 'bg-rose-100 text-red-800 border-red-300',
      iconBg: 'bg-red-50 border-red-100'
    };
  } else if (rarity === 'Tối Thượng') {
    raritySymbol = '👑 Tối Thượng';
    themeClass = {
      bg: 'bg-yellow-100/30 hover:shadow-yellow-300',
      border: 'border-yellow-400 hover:border-yellow-500',
      text: 'text-yellow-950 font-black bg-clip-text',
      badge: 'bg-yellow-200 text-amber-900 border-yellow-350',
      iconBg: 'bg-yellow-100 border-yellow-200'
    };
  }
  return { raritySymbol, themeClass };
}

