  const handleGenerateAIQuestions = async () => {
    const selectedLesson = activePracticeLesson;
    if (!selectedLesson) {
      triggerToast("⚠️ Vui lòng chọn cụ thể một bài học!");
      return;
    }

    const qCount = Math.max(0, Number(aiCountQuiz) || 0);
    const tfCount = Math.max(0, Number(aiCountTf) || 0);
    const mCount = Math.max(0, Number(aiCountMatching) || 0);
    const gfCount = Math.max(0, Number(aiCountGapFill) || 0);
    const totalRequested = qCount + tfCount + mCount + gfCount;

    if (totalRequested === 0) {
      triggerToast("⚠️ Vui lòng nhập số lượng câu hỏi cần tạo lớn hơn 0!");
      return;
    }

    if (totalRequested > 30) {
      triggerToast("⚠️ Tổng số câu hỏi soạn thảo tối đa cho một lượt là 30 câu!");
      return;
    }

    setAiIsGenerating(true);
    setAiErrorMsg("");
    triggerToast(`🤖 Đang khởi tạo trí tuệ nhân tạo để soạn thảo ${totalRequested} câu hỏi cho bài: "${selectedLesson.title}"...`);
    if (typeof playTing === "function") playTing();

    try {
      const personalKey = localStorage.getItem('personal_gemini_api_key') || localStorage.getItem('gemini_api_key') || '';
      const response = await fetch('/api/generate-ai-questions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-gemini-key': personalKey
        },
        body: JSON.stringify({
          lessonId: selectedLesson.id,
          lessonTitle: selectedLesson.title,
          subject: selectedLesson.subject,
          grade: selectedLesson.grade,
          topicName: selectedLesson.topicName,
          quizCount: qCount,
          trueFalseCount: tfCount,
          matchingCount: mCount,
          gapFillCount: gfCount
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Gặp lỗi trong quá trình kết nối AI.");
      }

      const data = await response.json();
      if (data.questions && data.questions.length > 0) {
        setQuestionsList(prev => {
          // Keep current questions for this lesson, and append generated ones
          // Ensure we don't exceed 40 questions total
          const currentLessonQs = prev.filter(q => q.lessonId === selectedLesson.id);
          
          const allowedCount = Math.max(0, 40 - currentLessonQs.length);
          const newQs = data.questions.slice(0, allowedCount);
          
          if (newQs.length === 0) {
            triggerToast("⚠️ Kho câu hỏi ôn luyện của bài học đã đạt tối đa 40 câu!");
            return prev;
          }
          
          triggerToast(`✓ Thành công! AI đã biên soạn xong ${newQs.length} câu hỏi mới cho bài học.`);
          return [...prev, ...newQs];
        });
        if (typeof playTing === "function") playTing();
      } else {
        throw new Error("AI trả về danh sách câu hỏi trống.");
      }
    } catch (err: any) {
      console.error(err);
      setAiErrorMsg(err.message || "Lỗi tạo câu hỏi.");
      triggerToast(`❌ Thất bại: ${err.message || "Lỗi kết nối AI"}`);
    } finally {
      setAiIsGenerating(false);
    }
  };

