  // Sync function to extract and merge topics from lessonsList
  const handleSyncTopicsFromLessons = (silent: boolean = false) => {
    const uniqueMap = new Map<string, { subject: string; program: string; name: string }>();
    
    lessonsList.forEach((l) => {
      if (!l.topicName) return;
      const normalizedTopic = l.topicName.trim();
      if (!normalizedTopic) return;
      
      let txtSub = "Tin học";
      if (l.subject === "tieng_viet" || l.subject === "Tiếng Việt") txtSub = "Tiếng Việt";
      else if (l.subject === "toan" || l.subject === "Toán") txtSub = "Toán";
      else if (l.subject === "tieng_anh" || l.subject === "Tiếng Anh") txtSub = "Tiếng Anh";
      
      const program = l.programType || "Kết nối tri thức với cuộc sống";
      
      const key = `${txtSub.toLowerCase()}-${program.toLowerCase()}-${normalizedTopic.toLowerCase()}`;
      if (!uniqueMap.has(key)) {
        uniqueMap.set(key, {
          subject: txtSub,
          program: program,
          name: normalizedTopic
        });
      }
    });

    const mergedList = [...generalTopicsList];
    let addedCount = 0;

    uniqueMap.forEach((val) => {
      const exists = mergedList.some(
        (t) =>
          t.name.toLowerCase().trim() === val.name.toLowerCase().trim() &&
          (t.subject || "Tin học").toLowerCase() === val.subject.toLowerCase() &&
          (t.program || "Kết nối tri thức với cuộc sống").toLowerCase() === val.program.toLowerCase()
      );

      if (!exists) {
        let guessedOrder = mergedList.length + 1;
        const matchNum = val.name.match(/(?:Chủ đề|Chương|Unit)\s*(\d+)/i);
        if (matchNum && matchNum[1]) {
          guessedOrder = parseInt(matchNum[1], 10);
        }
        
        mergedList.push({
          id: `topic_${Math.random().toString(36).substr(2, 9)}`,
          name: val.name,
          order: guessedOrder,
          isHidden: false,
          program: val.program,
          subject: val.subject
        });
        addedCount++;
      }
    });

    // Sort final merged list by subject, program, and order
    mergedList.sort((a, b) => {
      const subA = (a.subject || "Tin học").localeCompare(b.subject || "Tin học");
      if (subA !== 0) return subA;
      const progA = (a.program || "Kết nối tri thức với cuộc sống").localeCompare(b.program || "Kết nối tri thức với cuộc sống");
      if (progA !== 0) return progA;
      return (a.order || 99) - (b.order || 99);
    });

    setGeneralTopicsList(mergedList);
    if (!silent) {
      triggerToast(`🔄 Đã đồng bộ thành công! Thêm mới ${addedCount} chủ đề từ danh sách Bài học.`);
    }
  };

