  const handleImportLevelsFromExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];
        const rawJson = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[];
        
        if (rawJson.length <= 1) {
          triggerToast("⚠️ File Excel rỗng hoặc không đúng định dạng cột!");
          return;
        }

        setLevelHistory(prev => [...prev, levelsList]);
        const currentLevels = [...levelsList];
        let importedCount = 0;
        let updateCount = 0;

        for (let i = 1; i < rawJson.length; i++) {
          const row = rawJson[i];
          if (!row || row.length < 2) continue;

          // Exclude columns like STT, we read level number (col B, index 1) and stars (col C, index 2)
          const levelNum = Number(row[1]);
          const starsReq = Number(row[2]);

          if (isNaN(levelNum) || isNaN(starsReq)) continue;

          const existingIdx = currentLevels.findIndex(l => l.index === levelNum);
          if (existingIdx >= 0) {
            currentLevels[existingIdx] = { index: levelNum, level: "Cấp độ " + levelNum, starsRequired: starsReq };
            updateCount++;
          } else {
            currentLevels.push({ index: levelNum, level: "Cấp độ " + levelNum, starsRequired: starsReq });
            importedCount++;
          }
        }

        currentLevels.sort((a, b) => a.index - b.index);
        setLevelsList(currentLevels);
        triggerToast(`📥 Đã nhập dữ liệu Cấp độ! Thêm mới ${importedCount} và cập nhật ${updateCount} Cấp độ.`);
      } catch (err) {
        console.error(err);
        triggerToast("⚠️ Có lỗi xảy ra khi phân tích file Excel!");
      }
    };
    reader.readAsBinaryString(file);
    e.target.value = "";
  };

  const handleImportRewardsFromExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];
        const rawJson = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[];
        
        if (rawJson.length <= 1) {
          triggerToast("⚠️ File Excel rỗng hoặc không đúng định dạng cột!");
          return;
        }

        setRewardHistory(prev => [...prev, shopItemsList]);
        const currentRewards = [...shopItemsList];
        let importedCount = 0;
        let updateCount = 0;

        for (let i = 1; i < rawJson.length; i++) {
          const row = rawJson[i];
          if (!row || row.length < 3) continue;

          const rewardId = String(row[1] || '').trim();
          const title = String(row[2] || '').trim();
          const rarity = String(row[3] || 'Thường').trim();
          const desc = String(row[4] || '').trim();
          const icon = String(row[5] || '🎁').trim();
          const cost = Number(row[6] || 10);

          if (!rewardId || !title) continue;

          const existingIdx = currentRewards.findIndex(r => r.id.toLowerCase() === rewardId.toLowerCase());
          const meta = getRarityMeta(rarity);

          if (existingIdx >= 0) {
            currentRewards[existingIdx] = {
              id: rewardId,
              title,
              rarity: rarity as any,
              desc,
              icon,
              cost: isNaN(cost) ? 10 : cost,
              raritySymbol: meta.raritySymbol,
              themeClass: meta.themeClass
            };
            updateCount++;
          } else {
            currentRewards.push({
              id: rewardId,
              title,
              rarity: rarity as any,
              desc,
              icon,
              cost: isNaN(cost) ? 10 : cost,
              raritySymbol: meta.raritySymbol,
              themeClass: meta.themeClass
            });
            importedCount++;
          }
        }

        setShopItemsList(currentRewards);
        triggerToast(`📥 Đã nhập dữ liệu Phần thưởng! Thêm mới ${importedCount} và cập nhật ${updateCount} phần quà.`);
      } catch (err) {
        console.error(err);
        triggerToast("⚠️ Có lỗi xảy ra khi phân tích file Excel!");
      }
    };
    reader.readAsBinaryString(file);
    e.target.value = "";
  };

