  // --- STATE FOR ONLINE EXAMS TAB ---
  const [adminOnlineExams, setAdminOnlineExams] = useState<any[]>(() => {
    try {
      return JSON.parse(localStorage.getItem('lms_custom_exams') || '[]');
    } catch (e) {
      return [];
    }
  });
  const [selectedAdminExam, setSelectedAdminExam] = useState<any | null>(null);

  useEffect(() => {
    const syncWithServer = async () => {
      try {
        const res = await fetch('/api/exams');
        if (res.ok) {
          const serverList = await res.json();
          let localList = [];
          try {
            localList = JSON.parse(localStorage.getItem('lms_custom_exams') || '[]');
          } catch (e) {
            localList = [];
          }

          const mergedMap = new Map();
          localList.forEach((ex: any) => {
            if (ex && ex.id) mergedMap.set(ex.id, ex);
          });

          serverList.forEach((serverEx: any) => {
            if (serverEx && serverEx.id) {
              const localEx = mergedMap.get(serverEx.id);
              if (localEx) {
                // Merge submissions
                const subMap = new Map();
                (localEx.submissions || []).forEach((s: any) => {
                  if (s && s.id) subMap.set(s.id, s);
                });
                (serverEx.submissions || []).forEach((s: any) => {
                  if (s && s.id) subMap.set(s.id, s);
                });
                const mergedSubmissions = Array.from(subMap.values());
                
                const mergedAssignedIds = Array.isArray(serverEx.assignedTeacherIds)
                  ? serverEx.assignedTeacherIds
                  : (localEx.assignedTeacherIds || []);
                const mergedAssignedNames = Array.isArray(serverEx.assignedTeacherNames)
                  ? serverEx.assignedTeacherNames
                  : (localEx.assignedTeacherNames || []);
                
                mergedMap.set(serverEx.id, {
                  ...localEx,
                  ...serverEx,
                  assignedTeacherIds: mergedAssignedIds,
                  assignedTeacherNames: mergedAssignedNames,
                  submissions: mergedSubmissions
                });
              } else {
                mergedMap.set(serverEx.id, serverEx);
              }
            }
          });

          const mergedList = Array.from(mergedMap.values());
          localStorage.setItem('lms_custom_exams', JSON.stringify(mergedList));
          setAdminOnlineExams(mergedList);
          
          if (selectedAdminExam) {
            const updated = mergedList.find((ex: any) => ex.id === selectedAdminExam.id);
            if (updated) {
              setSelectedAdminExam(updated);
            }
          }
        }
      } catch (err) {
        console.error("Failed to sync custom exams:", err);
      }
    };

    syncWithServer();
    const interval = setInterval(syncWithServer, 3000);
    return () => clearInterval(interval);
  }, [selectedAdminExam?.id]);

  useEffect(() => {
    const handleSync = () => {
      try {
        const savedExams = localStorage.getItem('lms_custom_exams');
        if (savedExams) {
          const parsed = JSON.parse(savedExams);
          setAdminOnlineExams(parsed);
          
          if (selectedAdminExam) {
            const updated = parsed.find((ex: any) => ex.id === selectedAdminExam.id);
            if (updated) {
              setSelectedAdminExam(updated);
            }
          }
        }
      } catch (e) {
        console.error("Error syncing custom exams in AdminPanel:", e);
      }
    };
    window.addEventListener('lms_settings_changed', handleSync);
    return () => window.removeEventListener('lms_settings_changed', handleSync);
  }, [selectedAdminExam]);

  const [reportClassFilter, setReportClassFilter] = useState<string>('all');
