  // AI-generated answer guide/instructions for a theory question in Ngăn 1
  const handleSuggestAnswerGuide = async (q: any, qIndex: number) => {
    if (!q.questionText) {
      triggerToast("⚠️ Thầy Cô vui lòng nhập nội dung câu hỏi trước khi yêu cầu AI đề xuất hướng dẫn!");
      return;
    }
    setSuggestingGuideId(q.id || String(qIndex));
    triggerToast("⚡ Đang kết nối với trí tuệ nhân tạo Gemini để soạn thảo hướng dẫn làm bài...");
    try {
      const response = await fetch('/api/generate-question-explanation', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-gemini-key': localStorage.getItem('gemini_api_key') || ''
        },
        body: JSON.stringify({
          questionText: q.questionText,
          type: q.type,
          options: q.options || null,
          correctAnswer: q.correctAnswer || '',
          statements: q.statements || null,
          matchingPairs: q.matchingPairs || null
        })
      });
      if (!response.ok) {
        throw new Error("Lỗi mạng khi gọi API.");
      }
      const data = await response.json();
      if (data.explanation) {
        const updated = [...examFormTheory];
        updated[qIndex] = { 
          ...updated[qIndex], 
          answerGuide: data.explanation, 
          explanation: data.explanation 
        };
        setExamFormTheory(updated);
        triggerToast("✓ Đã cập nhật dòng 'Hướng dẫn làm bài sỹ tử' tự động bằng AI!");
        if (typeof playTing === 'function') {
          playTing();
        }
      } else {
        throw new Error("Không có phản hồi hợp lệ.");
      }
    } catch (err) {
      console.error(err);
      triggerToast("❌ Gặp sự cố không thể tự động đề xuất hướng dẫn làm bài.");
    } finally {
      setSuggestingGuideId(null);
    }
  };

  // States for online exams custom confirmation modals to bypass window.confirm check:
