  // Handler for Quick Removing a Single Assigned Teacher from an Exam
  const handleQuickRemoveAssignedTeacher = (examItem: any, teacherIdToRemove: string) => {
    if (!examItem) return;
    const updatedIds = (examItem.assignedTeacherIds || []).filter((id: string) => id !== teacherIdToRemove);
    const updatedNames = teachers
      .filter(t => updatedIds.includes(t.teacherId) || updatedIds.includes(t.id))
      .map(t => t.fullname);

    setAdminOnlineExams(prev => {
      const updated = prev.map(ex => {
        if (ex.id === examItem.id) {
          return {
            ...ex,
            assignedTeacherIds: updatedIds,
            assignedTeacherNames: updatedNames
          };
        }
        return ex;
      });
      localStorage.setItem('lms_custom_exams', JSON.stringify(updated));
      return updated;
    });

    if (selectedAdminExam?.id === examItem.id) {
      setSelectedAdminExam((prev: any) => prev ? {
        ...prev,
        assignedTeacherIds: updatedIds,
        assignedTeacherNames: updatedNames
      } : null);
    }

    try {
      fetch(`/api/exams/${examItem.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...examItem,
          assignedTeacherIds: updatedIds,
          assignedTeacherNames: updatedNames
        })
      }).catch(err => console.error("Sync quick remove assigned teacher to server error:", err));
    } catch (e) {}

    dispatchSettingsChanged();
    const removedTeacher = teachers.find(t => t.teacherId === teacherIdToRemove || t.id === teacherIdToRemove);
    triggerToast(`🗑️ Đã xóa GV "${removedTeacher?.fullname || teacherIdToRemove}" khỏi phân công chấm bài!`);
  };


  // --- DIALOG MODALS TRIGGER CONTROLS ---
