  // --- BULK GRADE LEVEL PROMOTIONS (Chuyển khối hàng loạt) ---
  const handleExecuteBulkGrade = () => {
    pushStudentStateToHistory(students);

    let count = 0;
    setStudents(prev => prev.map(s => {
      if (bulkGradeOption === 'ALL') {
        // Promoted up by +1 block level
        const currentGradeNum = s.grade;
        const targetGradeNum = currentGradeNum + 1 > 5 ? 5 : currentGradeNum + 1;
        
        // Attempt to find or derive target class format, like "3.1" -> "4.1"
        const classParts = s.className.split('.');
        let tentativeClass = s.className;
        if (classParts.length === 2 && Number(classParts[0]) === currentGradeNum) {
          tentativeClass = `${targetGradeNum}.${classParts[1]}`;
        }

        // Add to pool if it doesn't exist
        const availableClassesForTarget = classesByGrade[targetGradeNum] || [];
        if (!availableClassesForTarget.includes(tentativeClass) && targetGradeNum > currentGradeNum) {
          availableClassesForTarget.push(tentativeClass);
          classesByGrade[targetGradeNum] = availableClassesForTarget.sort();
        }

        count++;
        return {
          ...s,
          grade: targetGradeNum,
          className: tentativeClass
        };
      } else {
        // Specific filter
        if (s.grade === bulkCurrentGrade) {
          const classParts = s.className.split('.');
          let tentativeClass = s.className;
          if (classParts.length === 2 && Number(classParts[0]) === bulkCurrentGrade) {
            tentativeClass = `${bulkTargetGrade}.${classParts[1]}`;
          }

          // Add class room to target list if not already there
          const availableForTarget = classesByGrade[bulkTargetGrade] || [];
          if (!availableForTarget.includes(tentativeClass)) {
            availableForTarget.push(tentativeClass);
            classesByGrade[bulkTargetGrade] = availableForTarget.sort();
          }

          count++;
          return {
            ...s,
            grade: bulkTargetGrade,
            className: tentativeClass
          };
        }
      }
      return s;
    }));

    setActiveModal(null);
    triggerToast(`📊 Chuyển Khối Hàng Loạt hoàn tất! Đã chuyển ${count} học sinh thành công.`);
  };


  // --- BULK CLASS LEVEL MIGRATIONS (Chuyển Lớp hàng loạt) ---
  const handleExecuteBulkClass = () => {
    if (!bulkCurrentClass || !bulkTargetClass) {
      triggerToast("⚠️ Vui lòng chọn lớp học nguồn và lớp học đích!");
      return;
    }
    pushStudentStateToHistory(students);

    let count = 0;
    setStudents(prev => prev.map(s => {
      if (s.grade === bulkClassGrade && s.className === bulkCurrentClass) {
        count++;
        return {
          ...s,
          className: bulkTargetClass
        };
      }
      return s;
    }));

    setActiveModal(null);
    triggerToast(`🏫 Đổi Lớp Hàng Loạt thành công! Đã chuyển ${count} học sinh từ Lớp ${bulkCurrentClass} sang Lớp ${bulkTargetClass}.`);
  };


