  // --- REAL EXCEL FILE WRITING ENGINE (XLSX Export - Có viền quanh ôm văn bản vừa ô) ---
  const handleExportToExcel = () => {
    if (activeTab === 'students') {
      const dataToExport = filteredStudents.map((s, index) => ({
        'Mã học sinh (ID)': s.studentId,
        'Số thứ tự': index + 1,
        'Họ và tên': s.fullname,
        'Giới tính': s.gender || 'Nam',
        'Trường học': s.school,
        'Khối lớp': s.grade,
        'Tên Lớp': s.className
      }));

      const ws = XLSX.utils.json_to_sheet([]);
      XLSX.utils.sheet_add_json(ws, dataToExport, { origin: "A1" });
      
      // Auto formatting col widths (văn bản vừa ô)
      const widths = [18, 12, 28, 15, 35, 12, 12];
      ws['!cols'] = widths.map(w => ({ wch: w }));
      
      // SheetJS workbook compilation
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Dữ liệu Học sinh");
      
      XLSX.writeFile(wb, "Bieu-mau-hoc-sinh.xlsx");
      triggerToast("📥 Đã xuất thành công tệp Excel bài bản (.xlsx) Học sinh có gridlines!");
    } else if (activeTab === 'teachers') {
      const dataToExport = filteredTeachers.map((t, index) => ({
        'ID Giáo viên': t.teacherId,
        'Số thứ tự': index + 1,
        'Họ tên': t.fullname,
        'Giới tính': t.gender || 'Nam',
        'Trường học': t.school,
        'Khối Giảng dạy': t.grades.join(', '),
        'Lớp Phụ trách': t.classes.join(', ')
      }));

      const ws = XLSX.utils.json_to_sheet([]);
      XLSX.utils.sheet_add_json(ws, dataToExport, { origin: "A1" });
      
      const widths = [18, 12, 28, 15, 35, 20, 25];
      ws['!cols'] = widths.map(w => ({ wch: w }));
      
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Dữ liệu Giáo viên");
      XLSX.writeFile(wb, "Bieu-mau-giao-vien.xlsx");
      triggerToast("📥 Đã xuất thành công tệp Excel bài bản (.xlsx) Giáo viên!");
    } else if (activeTab === 'lessons') {
      const dataToExport = lessonsList.map((l, index) => {
        let txtSub = "Tin học";
        if (l.subject === "tieng_viet") txtSub = "Tiếng Việt";
        else if (l.subject === "toan") txtSub = "Toán";
        else if (l.subject === "tieng_anh") txtSub = "Tiếng Anh";
        return {
          'Số thứ tự': index + 1,
          'Môn học': txtSub,
          'Khối': l.grade,
          'Chương trình': l.programType,
          'Chủ đề': l.topicName,
          'Bài học': l.title
        };
      });

      const ws = XLSX.utils.json_to_sheet([]);
      XLSX.utils.sheet_add_json(ws, dataToExport, { origin: "A1" });
      
      const widths = [12, 18, 12, 18, 40, 45];
      ws['!cols'] = widths.map(w => ({ wch: w }));
      ws['!views'] = [{ showGridLines: true }];

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Danh sách Bài học");
      XLSX.writeFile(wb, "Danh_sach_bai_hoc.xlsx");
      triggerToast("📥 Đã xuất thành công Bản đồ Bài học (.xlsx) chuẩn chỉnh!");
    }
  };


  // --- REAL EXCEL FILE IMPORT PARSING ENGINE (XLSX Import - Không trùng ID) ---
  const handleImportFromExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];
        
        // Output array of arrays format to parse exact columns easily
        const rawJson = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[];
        
        if (rawJson.length <= 1) {
          triggerToast("⚠️ File Excel rỗng hoặc không đúng định dạng cột quy định!");
          return;
        }

        if (activeTab === 'students') {
          pushStudentStateToHistory(students);
          let importedCount = 0;
          let skipCount = 0;
          const currentStudents = [...students];

          // Column formats: Cột A: ID học sinh, Cột B: Số thứ tự, Cột C: Họ tên, Cột D: Giới tính, Cột E: Trường, Cột F: Khối, Cột G: Lớp
          for (let i = 1; i < rawJson.length; i++) {
            const row = rawJson[i];
            if (!row || row.length === 0) continue;

            const excelStudentId = String(row[0] || '').trim();
            const excelName = String(row[2] || '').trim();
            const excelGender = String(row[3] || 'Nam').trim();
            const excelSchool = String(row[4] || '').trim();
            const excelGrade = Number(row[5]);
            const excelClassName = String(row[6] || '').trim();

            if (!excelStudentId || !excelName) continue;

            // Strict unique check: Nếu trùng ID học sinh thì KHÔNG nhập học sinh đó lên
            const isColliding = currentStudents.some(s => s.studentId.trim().toLowerCase() === excelStudentId.toLowerCase());
            if (isColliding) {
              skipCount++;
              continue;
            }

            // Sync with dynamic categories pools if added in excel
            if (excelSchool && !schoolsList.includes(excelSchool)) {
              setSchoolsList(prev => [...prev, excelSchool]);
            }
            if (excelGrade && !gradesList.includes(excelGrade)) {
              setGradesList(prev => [...prev, excelGrade].sort((a,b)=>a-b));
            }
            if (excelGrade && excelClassName) {
              const classArray = classesByGrade[excelGrade] || [];
              if (!classArray.includes(excelClassName)) {
                setClassesByGrade(prev => ({
                  ...prev,
                  [excelGrade]: [...classArray, excelClassName].sort()
                }));
              }
            }

            currentStudents.push({
              id: `s_xls_${Date.now()}_${i}`,
              studentId: excelStudentId,
              fullname: excelName,
              username: `hs_${excelStudentId.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}`,
              password: '123',
              gender: excelGender,
              school: excelSchool || 'Tiểu học Trần văn Danh',
              grade: excelGrade || 3,
              className: excelClassName || '3.1',
              xp: 120,
              level: 1,
              streak: 1
            });
            importedCount++;
          }

          setStudents(currentStudents);
          triggerToast(`📥 Excel Import Đã hoàn tất! Nhập thành công ${importedCount} học sinh mới (Đã bộ lọc trùng bỏ qua ${skipCount} bản trùng ID).`);
        } else if (activeTab === 'teachers') {
          pushTeacherStateToHistory(teachers);
          let importedCount = 0;
          let skipCount = 0;
          const currentTeachers = [...teachers];

          // Columns layout: Cột A: ID Giáo viên, Cột B: Số thứ tự, Cột C: Họ tên, Cột D: Giới tính, Cột E: Trường, Cột F: Khối, Cột G: Lớp
          for (let i = 1; i < rawJson.length; i++) {
            const row = rawJson[i];
            if (!row || row.length === 0) continue;

            const excelTeacherId = String(row[0] || '').trim();
            const excelName = String(row[2] || '').trim();
            const excelGender = String(row[3] || 'Nam').trim();
            const excelSchool = String(row[4] || '').trim();
            const excelGradeRaw = String(row[5] || '').trim();
            const excelClassRaw = String(row[6] || '').trim();

            if (!excelTeacherId || !excelName) continue;

            // Check duplicate GV ID
            const isColliding = currentTeachers.some(t => t.teacherId.trim().toLowerCase() === excelTeacherId.toLowerCase());
            if (isColliding) {
              skipCount++;
              continue;
            }

            // Normalize grade arrays and classes arrays from comma separated strings in Excel file
            const blockGrades = excelGradeRaw.split(',').map(g => Number(g.trim())).filter(g => !isNaN(g) && g > 0);
            const blockClasses = excelClassRaw.split(',').map(c => c.trim()).filter(c => c.length > 0);

            // Sync with dynamic categories pools
            if (excelSchool && !schoolsList.includes(excelSchool)) {
              setSchoolsList(prev => [...prev, excelSchool]);
            }

            currentTeachers.push({
              id: `t_xls_${Date.now()}_${i}`,
              teacherId: excelTeacherId,
              fullname: excelName,
              username: `gv_${excelTeacherId.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()}`,
              password: '123',
              gender: excelGender,
              school: excelSchool || 'Tiểu học Trần văn Danh',
              subject: 'Tin học',
              grades: blockGrades.length ? blockGrades : [3],
              classes: blockClasses.length ? blockClasses : ['3.1']
            });
            importedCount++;
          }

          setTeachers(currentTeachers);
          triggerToast(`📥 Excel Import Giáo Viên hoàn tất! Thêm thành công ${importedCount} giáo viên (Bỏ qua ${skipCount} bản trùng lặp ID).`);
        } else if (activeTab === 'lessons') {
          setLessonsHistory(prev => [...prev, lessonsList]);
          let importedCount = 0;
          const currentLessons = [...lessonsList];

          // Column formats: Cột A: Số thứ tự, Cột B: Môn học, Cột C: Khối, Cột D: Chương trình, Cột E: Chủ đề, Cột F: Bài học
          for (let i = 1; i < rawJson.length; i++) {
            const row = rawJson[i];
            if (!row || row.length < 5) continue;

            const excelSubjRaw = String(row[1] || 'Tin học').trim();
            let subjectVal = 'tin_hoc';
            if (excelSubjRaw === 'Tiếng Việt') subjectVal = 'tieng_viet';
            else if (excelSubjRaw === 'Toán') subjectVal = 'toan';
            else if (excelSubjRaw === 'Tiếng Anh') subjectVal = 'tieng_anh';

            const excelGrade = Number(row[2] || 3);
            const excelProgRaw = String(row[3] || 'Kết nối tri thức với cuộc sống').trim();
            const excelProg = excelProgRaw === 'GDPT2018' || excelProgRaw === 'GDPT 2018' || excelProgRaw === 'Kết nối tri thức với cuộc sống'
              ? 'Kết nối tri thức với cuộc sống'
              : 'Tin học Quốc tế IC3 Spark';
            const excelTopic = String(row[4] || '').trim();
            const excelLessonTitle = String(row[5] || '').trim();

            if (!excelTopic || !excelLessonTitle) continue;

            currentLessons.push({
              id: `l_imp_${Date.now()}_${i}`,
              programType: excelProg,
              grade: excelGrade,
              topicName: excelTopic,
              lessonNumber: i,
              title: excelLessonTitle,
              shortDescription: `Mô tả tóm tắt bài giảng môn ${excelSubjRaw} thuộc chủ đề ${excelTopic}.`,
              videoUrl: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
              pdfUrl: `Tài liệu hướng dẫn bài ${excelLessonTitle}.`,
              infographicUrl: `🎯 Infographic bài học ${excelLessonTitle}: Khám phá lý thú bài viết để ghi nhận kiến thức!`,
              illustrationUrl: '🎨 Minh họa thuộc kho học liệu.',
              colorTheme: 'pastel-pink',
              subject: subjectVal,
              bookSeries: 'Kết nối tri thức với cuộc sống'
            });
            importedCount++;
          }

          setLessonsList(currentLessons);
          triggerToast(`✨ Nhập thành công ${importedCount} Bài học mới từ Excel!`);
        } else if (activeTab === 'games') {
          setGamesHistory(prev => [...prev, gamesList]);
          let importedCount = 0;
          let skipCount = 0;
          const currentGames = [...gamesList];

          // Columns layout: Cột A: STT, Cột B: ID trò chơi, Cột C: Thể loại, Cột D: Tên Trò chơi, Cột E: Mô tả, Cột F: Phần thưởng, Cột G: Trạng thái
          for (let i = 1; i < rawJson.length; i++) {
            const row = rawJson[i];
            if (!row || row.length === 0) continue;

            const excelGameId = String(row[1] || '').trim();
            const excelCategory = String(row[2] || 'Trò chơi luyện tập').trim();
            const excelTitle = String(row[3] || '').trim();
            const excelDesc = String(row[4] || '').trim();
            const excelReward = String(row[5] || '+30⭐').trim();
            const excelStatus = String(row[6] || 'Đang hoạt động').trim();

            if (!excelGameId || !excelTitle) continue;

            // Chống trùng ID: Nếu trùng ID trò chơi thì KHÔNG nhập trò chơi đó lên
            const isColliding = currentGames.some(g => g.id.trim().toLowerCase() === excelGameId.toLowerCase());
            if (isColliding) {
              skipCount++;
              continue;
            }

            currentGames.push({
              id: excelGameId,
              title: excelTitle,
              category: excelCategory,
              description: excelDesc,
              reward: excelReward,
              status: excelStatus === 'Tạm khóa' ? 'Tạm khóa' : 'Đang hoạt động',
              gameAreaType: 'link',
              externalLink: ''
            });
            importedCount++;
          }

          setGamesList(currentGames);
          triggerToast(`📥 Nhập thành công ${importedCount} Trò chơi mới từ Excel (Đã bỏ qua ${skipCount} trò chơi trùng lặp ID).`);
        }
      } catch (err) {
        console.error(err);
        triggerToast("❌ Có lỗi xảy ra trong quá trình giải mã tệp Excel!");
      }
    };
    reader.readAsBinaryString(file);
    // Reset file input value count
    e.target.value = '';
  };


