                {activeModal === 'add_student' && '➕ Thêm mới học sinh'}
                {activeModal === 'edit_student' && '✏️ Chỉnh sửa thông tin học sinh'}
                {activeModal === 'add_teacher' && '👩‍🏫 Thêm mới Giáo viên'}
                {activeModal === 'edit_teacher' && '✏️ Chỉnh sửa thông tin Giáo viên'}
                {activeModal === 'bulk_grade' && '📈 Chuyển khối'}
                {activeModal === 'bulk_class' && '🏫 Chuyển lớp'}
                {activeModal === 'delete_student' && '⚠️ Xác nhận xóa Học sinh'}
                {activeModal === 'delete_teacher' && '⚠️ Xác nhận xóa Giáo viên'}
